// This file is generated by AI.

// 从训练切分产物导入角色。
//
// 交互刻意做成**一个对话框 + 两个路径输入框**:
// 之前是"依次弹出两个系统目录选择框", 用户点完第一个还要再点第二个, 中间没有任何
// 反馈, 很容易以为操作已经结束。这里把两个路径都摆在面前, 各自配一个文件夹图标,
// 一次点"导入"即可。

import { Button, Field, Input } from '@fluentui/react-components';
import { FolderRegular } from '@fluentui/react-icons';
import { open as openDialog } from '@tauri-apps/plugin-dialog';
import { useState } from 'react';

import { AppDialog } from '../components/AppDialog';
import { voiceController } from './controller';

interface Props {
  onClose: () => void;
  onImported: (message: string) => void;
  onError: (error: string | null) => void;
}

export function ListImportDialog({ onClose, onImported, onError }: Props) {
  const [listPath, setListPath] = useState('');
  const [audioDir, setAudioDir] = useState('');
  const [busy, setBusy] = useState(false);

  const pickList = async () => {
    const picked = await openDialog({
      multiple: false,
      title: '选择清单文件',
      filters: [{ name: '文本清单', extensions: ['list', 'txt'] }],
    });
    if (typeof picked === 'string') setListPath(picked);
  };

  const pickAudioDir = async () => {
    const picked = await openDialog({ directory: true, multiple: false, title: '选择音频目录' });
    if (typeof picked === 'string') setAudioDir(picked);
  };

  const ready = listPath.trim().length > 0 && audioDir.trim().length > 0 && !busy;

  const run = async () => {
    if (!ready) return;
    setBusy(true);
    onError(null);
    try {
      const report = await voiceController.importFromList(listPath.trim(), audioDir.trim());
      onImported(
        `已导入 ${report.imported} 条参考音频，涉及 ${report.characters.length} 个角色` +
          (report.autoTrimmed > 0 ? `，其中 ${report.autoTrimmed} 条过长已自动裁剪` : '') +
          (report.skipped > 0 ? `，跳过 ${report.skipped} 条（音频缺失或无法读取）` : '')
      );
      onClose();
    } catch (caught) {
      onError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  return (
    <AppDialog
      title="从清单导入角色"
      description="选择训练切分产物里的清单文件与音频目录。匹配按**文件名**进行，因此两者放在哪里都可以。"
      size="medium"
      height={360}
      onClose={onClose}
      footer={
        <>
          <Button appearance="secondary" disabled={busy} onClick={onClose}>
            取消
          </Button>
          <Button appearance="primary" disabled={!ready} onClick={() => void run()}>
            {busy ? '导入中…' : '导入'}
          </Button>
        </>
      }
    >
      <Field label="清单文件（.list）">
        <div className="workbench-input-row">
          <Input
            value={listPath}
            readOnly
            placeholder="选择包含 路径|说话者|语言|文本 的 .list 文件"
            title={listPath}
          />
          <Button
            appearance="secondary"
            icon={<FolderRegular />}
            title="选择清单文件"
            onClick={() => void pickList()}
          />
        </div>
      </Field>

      <Field label="音频目录">
        <div className="workbench-input-row">
          <Input value={audioDir} readOnly placeholder="选择存放切分音频的目录（可嵌套子目录）" title={audioDir} />
          <Button
            appearance="secondary"
            icon={<FolderRegular />}
            title="选择音频目录"
            onClick={() => void pickAudioDir()}
          />
        </div>
      </Field>

      <p className="voice-dialog-hint">
        同一个角色最多导入 48 条参考音频；过短的音频会在尾部补静音，过长的会按静音边界裁剪。
      </p>
    </AppDialog>
  );
}
